import { focusRing } from "@/lib/beton/shared";
import { tv, type VariantProps } from "@/lib/beton/tv";

export const card = tv({
  slots: {
    root: "flex flex-col rounded-md border-3 border-border text-foreground",
    header: "flex flex-col gap-1.5 p-6 pb-0",
    title: "font-display text-2xl font-extrabold leading-tight tracking-tight",
    description: "text-base text-foreground",
    body: "flex flex-col gap-4 p-6",
    footer: "mt-auto flex flex-wrap items-center gap-3 border-t-3 border-border p-6",
  },
  variants: {
    variant: {
      primary: { root: "bg-primary" },
      secondary: { root: "bg-secondary" },
      ghost: { root: "bg-raised" },
      danger: { root: "bg-danger" },
    },
    elevation: {
      none: { root: "shadow-none" },
      sm: { root: "shadow-sm" },
      lg: { root: "shadow-lg" },
    },
    interactive: {
      true: {
        root: [
          "cursor-pointer transition-[translate,box-shadow] duration-70 ease-linear motion-reduce:transition-none",
          focusRing,
        ],
      },
    },
  },
  compoundVariants: [
    {
      interactive: true,
      elevation: "sm",
      class: { root: "active:translate-x-1 active:translate-y-1 active:shadow-none" },
    },
    {
      interactive: true,
      elevation: "lg",
      class: { root: "active:translate-x-3 active:translate-y-3 active:shadow-none" },
    },
  ],
  defaultVariants: {
    variant: "ghost",
    elevation: "sm",
    interactive: false,
  },
});

export type CardVariants = VariantProps<typeof card>;

import { card, type CardVariants } from "@/lib/beton/recipes/card.recipe";
import type { ComponentProps } from "react";
import { renderElement, type RenderProp } from "@/lib/beton/render-element";

const slots = card();

export interface CardProps extends ComponentProps<"div">, CardVariants {
  render?: RenderProp;
}

function CardRoot({
  variant = "ghost",
  elevation = "sm",
  interactive = false,
  className,
  render,
  ...props
}: CardProps) {
  return renderElement(
    "div",
    {
      ...props,
      "data-variant": variant,
      className: card({ variant, elevation, interactive }).root({ class: className }),
    },
    render,
  );
}

export interface CardPartProps extends ComponentProps<"div"> {
  render?: RenderProp;
}

function CardHeader({ className, render, ...props }: CardPartProps) {
  return renderElement("div", { ...props, className: slots.header({ class: className }) }, render);
}

export interface CardTitleProps extends ComponentProps<"h3"> {
  render?: RenderProp;
}

function CardTitle({ className, render, ...props }: CardTitleProps) {
  return renderElement("h3", { ...props, className: slots.title({ class: className }) }, render);
}

export interface CardDescriptionProps extends ComponentProps<"p"> {
  render?: RenderProp;
}

function CardDescription({ className, render, ...props }: CardDescriptionProps) {
  return renderElement(
    "p",
    { ...props, className: slots.description({ class: className }) },
    render,
  );
}

function CardBody({ className, render, ...props }: CardPartProps) {
  return renderElement("div", { ...props, className: slots.body({ class: className }) }, render);
}

function CardFooter({ className, render, ...props }: CardPartProps) {
  return renderElement("div", { ...props, className: slots.footer({ class: className }) }, render);
}

export const Card = Object.assign(CardRoot, {
  Header: CardHeader,
  Title: CardTitle,
  Description: CardDescription,
  Body: CardBody,
  Footer: CardFooter,
});
